#include <stdlib.h>
#include <stddef.h>
#include <stdalign.h>

#include "ast.h"
#include "error.h"



//  MEMORY HANDLING

static arena_t *ast_arena = NULL;


/* This function was generated by Gemini flash 3.8
    Prompt: "Implementuj funkci init_arena pro AST" */
/**
 * @brief Aligns size in arena for 8-byte memory
 * 
 * @param size in bytes
 * 
 * @return aligned size
 */
static unsigned align_size(unsigned size)
{
    const unsigned alignment = alignof(max_align_t);
    return (size + (alignment - 1)) & ~(alignment - 1);
}


/* The lines of code within this function were generated by Gemini flash 3.8
    AND WERE MODIFIED with custom error exit function and custom names of structs
    Prompt: "Implementuj funkci init_arena pro AST" */
void ast_init_arena()
{
    ast_arena = malloc(sizeof(arena_t));
    if(ast_arena == NULL) {
        error_exit(INTERNAL_ERR, 0, "Memory allocation failed");
        return;
    }

    ast_arena->offset = 0;
    ast_arena->next = NULL;
}


/* The lines of code within this function were generated by Gemini flash 3.8
    AND WERE MODIFIED with custom error exit function, custom names of structs and translated comments
    Prompt: "Implementuj funkci init_arena pro AST" */
/**
 * @brief Allocates 1 block of memory (1 arena)
 * 
 * @param size in bytes
 */
static void *ast_alloc_node(unsigned size)
{
   size = align_size(size);

    if(ast_arena == NULL) {
        ast_init_arena();
        if(ast_arena == NULL) {
            return NULL;
        }
    }

    // Allocation of next arena in case first block of data gets filled up 
    if(ast_arena->offset + size > ARENA_SIZE) {
        arena_t *new_arena = malloc(sizeof(arena_t));
        if(new_arena == NULL) {
            error_exit(INTERNAL_ERR, 0, "Memory allocation failed");
            return NULL;
        }

        new_arena->offset = 0;
        new_arena->next = ast_arena; // Block intertwining
        ast_arena = new_arena;
    }

    void *ptr = &ast_arena->arena[ast_arena->offset];
    ast_arena->offset += (int)size;

    return ptr;
}


/* This function was generated by Gemini flash 3.8
    AND WAS MODIFIED with custom struct name
    Prompt: "Implementuj funkci init_arena pro AST" */
void ast_free_arena(void)
{
    arena_t *current = ast_arena;
    while (current != NULL) {
        arena_t *next = current->next;
        free(current);
        current = next;
    }
    ast_arena = NULL;
}



//  HELPER FUNCTIONS

ast_node_t *ast_node_init(ast_stmt_type_t stmt_type, unsigned line_num)
{
    ast_node_t *node = ast_alloc_node(sizeof(ast_node_t));
    node->data = ast_alloc_node(sizeof(ast_node_data_t));
    node->next = NULL;

    node->stmt_type = stmt_type;
    node->line_num = line_num;

    return node;
}



//  AST INSERT FUNCTIONS

ast_node_t *ast_insert_var_declaration(char value[MAX_LENGTH], unsigned line_num, bool is_mutable,
                                            token_type data_type, ast_node_t *expression)
{
    ast_node_t *current_node = ast_node_init(AST_DECLARATION, line_num);

    strcpy(current_node->data->declaration_node.id_val, value);
    current_node->data->declaration_node.is_mutable = is_mutable;
    current_node->data->declaration_node.data_type = data_type;
    current_node->data->declaration_node.expression = expression;
    
    return current_node;
}



//  EXPR INSERT FUNCTIONS

ast_node_t *expr_insert_op(ast_stmt_type_t opr, unsigned line_num, ast_node_t *left, ast_node_t *right)
{
    ast_node_t *op_node = ast_node_init(opr, line_num);

    op_node->data->op_node.left = left;
    op_node->data->op_node.right = right;

    return op_node;
}


ast_node_t *expr_insert_id_leaf(char value[MAX_LENGTH], unsigned line_num)
{
    ast_node_t *leaf_node = ast_node_init(EXPR_IDENTIFIER, line_num);
    strcpy(leaf_node->data->id_leaf_node.id_val, value);

    return leaf_node;
}


ast_node_t *expr_insert_lit_leaf(token_value_t lit_value, unsigned line_num, token_type lit_type)
{
    ast_node_t *leaf_node = ast_node_init(EXPR_LITERAL, line_num);

    leaf_node->data->lit_leaf_node.lit_type = lit_type;
    leaf_node->data->lit_leaf_node.lit_value = lit_value;

    return leaf_node;
}
